discoveries.query:
PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT DISTINCT ?book ?identifier ?isbn WHERE {
  VALUES ?isbn { "4785977388" "9784785977382" }
  ?book a class:MangaBook ; schema:isbn ?isbn .
  OPTIONAL { ?book schema:identifier ?identifier }
} ORDER BY ?book ?identifier ?isbn LIMIT 20

